81	function _log(msg, level, ctx) {
82	  level = level || 'info'
83	  try {
84	    if (typeof global !== 'undefined' && global.addRuntimeLog) {
85	      var prefix = '[引擎] '
86	      if (ctx) prefix += '[' + ctx + '] '
87	      global.addRuntimeLog(prefix + msg, level)
88	    }
89	    if (C.debug && console) {
90	      console.log('[' + level.toUpperCase() + '] ' + msg)
91	    }
92	  } catch(e) {}
93	}
