504	  async _loadAllMaps() {
505	    if (this.maps.length === 0) {
506	      _logInfo('没有Map配置，跳过加载', 'map')
507	      return
508	    }
509	  
510	    // 快速启动模式跳过预加载
511	    if (this._isQuickLaunch) {
512	      _logInfo('快速启动模式，跳过Map预加载', 'map')
513	      return
514	    }
515	  
516	    var preloadConfig = this.config.mapPreload || { enabled: false, maxMaps: 0 }
517	  
518	    // 按需加载模式：只检查缓存
519	    if (!preloadConfig.enabled) {
520	      await this._checkAllMapsCache()
521	      return
522	    }
523	  
524	    // ====== 预加载模式：直接调用 _ensureMap ======
525	    var maxMaps = preloadConfig.maxMaps || 0
526	    var totalMaps = this.maps.length
527	    var loadCount = (maxMaps === 0) ? totalMaps : Math.min(maxMaps, totalMaps)
528	  
529	    _logInfo('预加载模式：加载前 ' + loadCount + '/' + totalMaps + ' 个Map', 'map')
530	  
531	    for (var i = 0; i < loadCount; i++) {
532	      // 直接用 _ensureMap 加载，它会处理缓存/文件/内存
533	      var mapData = await this._ensureMap(i)
534	      if (mapData) {
535	        _logInfo('Map ' + i + ' 预加载成功', 'map')
536	      } else {
537	        _logWarn('Map ' + i + ' 预加载失败', 'map')
538	      }
539	  
540	      // 每加载 3 个休息 100ms
541	      if (i % 3 === 2) {
542	        await new Promise(resolve => setTimeout(resolve, 100))
543	      }
544	    }
545	  
546	    _logSuccess('Map预加载完成', 'map')
547	  }
