549	/**
550	 * 仅检查 Map 缓存是否存在，不加载到内存
551	 * 用于按需加载模式
552	 */
553	async _checkAllMapsCache() {
554	  _logInfo('检查 ' + this.maps.length + ' 个Map缓存', 'map')
555	  this._cachedMaps = {}
556	  
557	  for (var i = 0; i < this.maps.length; i++) {
558	    try {
559	      var mapData = await this._loadMapFromCache(i)
560	      this._cachedMaps[i] = !!mapData
561	      if (this._cachedMaps[i]) {
562	        _logInfo('Map ' + i + ' 缓存存在', 'map')
563	      } else {
564	        // 尝试构建缓存
565	        mapData = await this._loadMapFromFile(i)
566	        if (mapData) {
567	          this._saveMapToCache(i, mapData)
568	          this._cachedMaps[i] = true
569	          _logInfo('Map ' + i + ' 已构建缓存', 'map')
570	        }
571	      }
572	    } catch(e) {
573	      _logError('检查Map ' + i + ' 失败: ' + e.message, 'map')
574	      this._cachedMaps[i] = false
575	    }
576	    
577	    if (i % 3 === 2) {
578	      await new Promise(resolve => setTimeout(resolve, 5))
579	    }
580	  }
581	  
582	  _logSuccess('Map缓存检查完成', 'map')
583	}
584	  // ========== Map 按需加载（搜索时调用） ==========
585	  async _ensureMap(mapId) {
586	    // 如果已经在内存中，移到最近使用位置
587	    if (this.mapData[mapId]) {
588	      var idx = this.loadedMapsOrder.indexOf(mapId)
589	      if (idx > -1) {
590	        this.loadedMapsOrder.splice(idx, 1)
591	        this.loadedMapsOrder.push(mapId)
592	      }
593	      return this.mapData[mapId]
594	    }
595	    
596	    _logInfo('加载 Map ' + mapId + ' 到内存', 'map')
597	    
598	    var mapData = await this._loadMapFromCache(mapId)
599	    if (!mapData) {
600	      mapData = await this._loadMapFromFile(mapId)
601	      if (mapData) {
602	        this._saveMapToCache(mapId, mapData)
603	      }
604	    }
605	    
606	    if (!mapData) {
607	      _logError('Map ' + mapId + ' 加载失败', 'map')
608	      return null
609	    }
610	    
611	    // ========== 新增：LRU 淘汰 ==========
612	    while (this.loadedMapsOrder.length >= this.maxLoadedMaps) {
613	      var oldest = this.loadedMapsOrder.shift()
