585	  async _ensureMap(mapId) {
586	    // 如果已经在内存中，移到最近使用位置
587	    if (this.mapData[mapId]) {
588	      var idx = this.loadedMapsOrder.indexOf(mapId)
589	      if (idx > -1) {
590	        this.loadedMapsOrder.splice(idx, 1)
591	        this.loadedMapsOrder.push(mapId)
592	      }
593	      return this.mapData[mapId]
594	    }
595	    
596	    _logInfo('加载 Map ' + mapId + ' 到内存', 'map')
597	    
598	    var mapData = await this._loadMapFromCache(mapId)
599	    if (!mapData) {
600	      mapData = await this._loadMapFromFile(mapId)
601	      if (mapData) {
602	        this._saveMapToCache(mapId, mapData)
603	      }
604	    }
605	    
606	    if (!mapData) {
607	      _logError('Map ' + mapId + ' 加载失败', 'map')
608	      return null
609	    }
610	    
611	    // ========== 新增：LRU 淘汰 ==========
612	    while (this.loadedMapsOrder.length >= this.maxLoadedMaps) {
613	      var oldest = this.loadedMapsOrder.shift()
614	      delete this.mapData[oldest]
615	      _logInfo('移除 Map ' + oldest + ' 释放内存', 'map')
616	    }
617	    
618	    // 存入内存
619	    this.mapData[mapId] = mapData
620	    this.loadedMapsOrder.push(mapId)
621	    
622	    return mapData
623	  }
